@@ -164,6 +164,18 @@ export function analyzeTierDeclarations(inputs: DriftInputs): TierDriftFinding[]
+export function analyzeTierTransitionEvents(
+  transitions: readonly TierTransitionPayload[]
+): TierDriftFinding[] {
+  const findings: TierDriftFinding[] = [];
+  for (const t of transitions) {
+    if (t.kind !== 'promotion') continue; // demotions are automatic — no vote required
+    const ref = t.ratificationVoteRef;
+    if (ref === undefined || ref.trim() === '') {
+      findings.push({
+        code: 'promotion-without-ratification',
+        message: `tier-transition promotion of '${t.subject}' (${t.fromTier} \u2192 ${t.toTier}) has NO linked ratificationVoteRef. Promotions MUST be ratification-linked (ADR-0017).`,
+      });
+    }
+  }
+  return findings;
+}

